PRAGMA foreign_keys = ON;
CREATE TABLE user (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, emailVerified INTEGER NOT NULL DEFAULT 0, image TEXT, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE TABLE session (id TEXT PRIMARY KEY, expiresAt INTEGER NOT NULL, token TEXT NOT NULL UNIQUE, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL, ipAddress TEXT, userAgent TEXT, userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE);
CREATE INDEX session_user ON session(userId);
CREATE TABLE account (id TEXT PRIMARY KEY, accountId TEXT NOT NULL, providerId TEXT NOT NULL, userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, accessToken TEXT, refreshToken TEXT, idToken TEXT, accessTokenExpiresAt INTEGER, refreshTokenExpiresAt INTEGER, scope TEXT, password TEXT, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE INDEX account_user ON account(userId);
CREATE TABLE verification (id TEXT PRIMARY KEY, identifier TEXT NOT NULL, value TEXT NOT NULL, expiresAt INTEGER NOT NULL, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE INDEX verification_identifier ON verification(identifier);
CREATE TABLE rateLimit (id TEXT PRIMARY KEY, key TEXT NOT NULL UNIQUE, count INTEGER NOT NULL, lastRequest INTEGER NOT NULL);
CREATE TABLE settings (user_id TEXT PRIMARY KEY REFERENCES user(id) ON DELETE CASCADE, data TEXT NOT NULL CHECK(json_valid(data)), updated_at TEXT NOT NULL);
CREATE TABLE records (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK(kind IN ('meal','recipe','weight','water','measurement','plan','session','wellness','activity')), date TEXT NOT NULL CHECK(length(date)=10), data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, request_id TEXT, source_id TEXT, UNIQUE(user_id,request_id), UNIQUE(user_id,kind,source_id));
CREATE INDEX records_user_kind_date ON records(user_id,kind,date DESC,id);
CREATE INDEX records_user_date ON records(user_id,date DESC,id);
CREATE UNIQUE INDEX one_wellness_day ON records(user_id,date) WHERE kind='wellness';
CREATE TABLE integrations (user_id TEXT PRIMARY KEY REFERENCES user(id) ON DELETE CASCADE, athlete_id TEXT NOT NULL, credential TEXT NOT NULL, start_date TEXT NOT NULL, cursor TEXT NOT NULL, imported_through TEXT, earliest_wellness TEXT, earliest_activity TEXT, latest_wellness TEXT, latest_activity TEXT, last_success TEXT, next_retry TEXT, failures INTEGER NOT NULL DEFAULT 0, lease_until TEXT, lease_id TEXT, status TEXT NOT NULL DEFAULT 'connected', error TEXT);
CREATE TABLE usage (bucket TEXT PRIMARY KEY, count INTEGER NOT NULL CHECK(count>=0), expires_at TEXT NOT NULL);
CREATE TABLE ai_requests (user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, request_id TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(user_id,request_id));
CREATE TABLE schema_version (version INTEGER PRIMARY KEY);
INSERT INTO schema_version VALUES (1);
